int main() {
    string s;
    cin >> s;

    int last[26];
    for (int i = 0; i < (int) s.size(); i++) last[s[i] - 'a'] = i;
    string stack;
    bool inStack[26] = {false};
    for (int i = 0; i < (int) s.size(); i++) {
        char ch = s[i];
        if (inStack[ch - 'a']) continue;
        while (!stack.empty() && stack.back() > ch && last[stack.back() - 'a'] > i) {
            inStack[stack.back() - 'a'] = false;
            stack.pop_back();
        }
        stack += ch;
        inStack[ch - 'a'] = true;
    }
    cout << stack << "\n";

    return 0;
}

